public static class TaskRules {
 public static string SearchText(TaskItem t){return (t.Title??"")+" "+(t.Project??"")+" "+(t.Tags??"");}
 public static string Description(TaskItem t){return String.Join(" · ",new[]{String.IsNullOrWhiteSpace(t.Project)?"":t.Project,String.IsNullOrWhiteSpace(t.Tags)?"":"#"+t.Tags.Replace(","," #"),t.RepeatKind=="week"?"每 "+t.RepeatEvery+" 周重复":t.RepeatKind=="month"?"每 "+t.RepeatEvery+" 月重复":""}.Where(s=>s.Length>0));}
 public static DateTime Next(DateTime value,string kind,int interval,int day){if(kind=="week")return value.AddDays(7*Math.Max(1,interval));var m=value.AddMonths(Math.Max(1,interval));return new DateTime(m.Year,m.Month,Math.Min(Math.Max(1,day),DateTime.DaysInMonth(m.Year,m.Month))).Add(value.TimeOfDay);}
 public static TaskItem Following(TaskItem task,DateTime now,bool future){
  var next=task.Copy();next.Id=Guid.NewGuid().ToString();next.RepeatNextId="";next.Done=false;next.Notified=false;next.EndNotified=false;next.Created=now;
  next.RepeatAnchorDay=task.RepeatAnchorDay>0?task.RepeatAnchorDay:(task.End??task.Start??task.Created).Day;
  next.RepeatStartDay=task.RepeatStartDay>0?task.RepeatStartDay:(task.Start??task.End??task.Created).Day;
  try{
   next.Start=task.Start.HasValue?(DateTime?)Next(task.Start.Value,task.RepeatKind,task.RepeatEvery,next.RepeatStartDay):null;
   next.End=task.End.HasValue?(DateTime?)Next(task.End.Value,task.RepeatKind,task.RepeatEvery,next.RepeatAnchorDay):null;
   if(!next.Start.HasValue&&!next.End.HasValue)next.Start=Next(task.Created.Date,task.RepeatKind,task.RepeatEvery,next.RepeatStartDay);
   for(int skip=0;skip<5200;skip++){
    if(future){if((next.End??next.Start??DateTime.MaxValue)>=now)break;}
    else {var following=Next((next.Start??next.End).Value,task.RepeatKind,task.RepeatEvery,next.Start.HasValue?next.RepeatStartDay:next.RepeatAnchorDay);if(following>now)break;}
    if(next.Start.HasValue)next.Start=Next(next.Start.Value,task.RepeatKind,task.RepeatEvery,next.RepeatStartDay);
    if(next.End.HasValue)next.End=Next(next.End.Value,task.RepeatKind,task.RepeatEvery,next.RepeatAnchorDay);
   }
   return next;
  }catch(ArgumentOutOfRangeException){return null;}
 }
 public static bool Repeats(TaskItem task){return (task.RepeatKind=="week"||task.RepeatKind=="month")&&String.IsNullOrEmpty(task.RepeatNextId);}
 public static void Complete(List<TaskItem> tasks,TaskItem task,bool done){task.Done=done;if(!done||!Repeats(task))return;var next=Following(task,DateTime.Now,true);if(next!=null){task.RepeatNextId=next.Id;tasks.Add(next);}}
 public static bool Advance(List<TaskItem> tasks,DateTime now){bool changed=false;foreach(var task in tasks.Where(Repeats).ToList()){var next=Following(task,now,false);if(next==null||(next.Start??next.End).Value>now)continue;task.RepeatNextId=next.Id;tasks.Add(next);changed=true;}return changed;}
 public static void TestAutomatic(){var now=new DateTime(2026,10,26,12,0,0);var old=new TaskItem{Title="每周自动",Start=now.AddDays(-21),RepeatKind="week"};var list=new List<TaskItem>{old};if(!Advance(list,now)||list.Count!=2||list[1].Start!=now||old.Done)throw new Exception("automatic recurring task");if(Advance(list,now)||list.Count!=2)throw new Exception("recurrence idempotence");Complete(list,old,true);if(list.Count!=2)throw new Exception("completed old task duplicates recurrence");var jan=new TaskItem{Title="月末",Start=new DateTime(2027,1,31,18,0,0),RepeatKind="month"};list=new List<TaskItem>{jan};if(!Advance(list,new DateTime(2027,3,31,20,0,0))||list[1].Start!=new DateTime(2027,3,31,18,0,0))throw new Exception("monthly missed periods");}

 public static void Test(){TestAutomatic();var task=new TaskItem{Title="周报",Project="工作",Tags="写作,例行",RepeatKind="week",RepeatEvery=1,End=DateTime.Today.AddDays(1).AddHours(18)};var list=new List<TaskItem>{task};Complete(list,task,true);if(list.Count!=2||list[1].End!=task.End.Value.AddDays(7)||list[1].Project!="工作")throw new Exception("weekly recurrence");Complete(list,task,true);if(list.Count!=2)throw new Exception("duplicate recurrence");var jan=new DateTime(2027,1,31,18,0,0);if(Next(Next(jan,"month",1,31),"month",1,31)!=new DateTime(2027,3,31,18,0,0))throw new Exception("monthly anchor");var s=new State{OffWorkTime="18:00",WorkdayDate=new DateTime(2026,10,26)};s.WeeklyOffWork[1]="19:30";if(WorkdayClock.Resolve(s)!="19:30")throw new Exception("weekly work schedule");s.WorkOverrideDate=s.WorkdayDate;s.WorkOverrideTime="17:00";if(WorkdayClock.Resolve(s)!="17:00")throw new Exception("work schedule override");}
}
public static partial class WorkdayClock {
 public static string Resolve(State s){TimeSpan value;if(s.WorkOverrideDate.Date==s.WorkdayDate.Date&&TryTime(s.WorkOverrideTime,out value))return s.WorkOverrideTime;int day=(int)s.WorkdayDate.DayOfWeek;if(s.WeeklyOffWork!=null&&s.WeeklyOffWork.Length==7&&TryTime(s.WeeklyOffWork[day],out value))return s.WeeklyOffWork[day];return s.OffWorkTime;}
}
public class RulesEditor : StackPanel {
 public CheckBox Enabled;TextBox project,tags,interval;ComboBox repeat;
 public RulesEditor(TaskItem task,bool bulk){Enabled=new CheckBox{Content=bulk?"修改项目、标签及重复规则":"项目、标签及重复",IsChecked=!bulk,Margin=new Thickness(0,12,0,6)};Children.Add(Enabled);var body=new StackPanel();Children.Add(body);project=Field(body,"项目（可留空）",task.Project,"任务项目");tags=Field(body,"标签（逗号分隔）",task.Tags,"任务标签");var row=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,5,0,5)};body.Children.Add(row);repeat=new ComboBox{ItemsSource=new[]{"不重复","每周","每月"},SelectedIndex=task.RepeatKind=="week"?1:task.RepeatKind=="month"?2:0,Width=110,Padding=new Thickness(5)};Ui.Name(repeat,"任务重复规则");row.Children.Add(repeat);row.Children.Add(Ui.T(" 间隔 ",12));interval=new TextBox{Text=Math.Max(1,task.RepeatEvery).ToString(),Width=44,Padding=new Thickness(5)};Ui.Name(interval,"重复间隔");row.Children.Add(interval);row.Children.Add(Ui.T(" 周 / 月",12));Action sync=()=>body.IsEnabled=Enabled.IsChecked==true;Enabled.Click+=(s,e)=>sync();sync();}
 static TextBox Field(Panel body,string label,string value,string name){var row=new DockPanel{Margin=new Thickness(0,3,0,3)};var text=Ui.T(label,11);text.Width=140;DockPanel.SetDock(text,Dock.Left);row.Children.Add(text);var input=new TextBox{Text=value??"",Padding=new Thickness(5),MaxLength=200};Ui.Name(input,name);row.Children.Add(input);body.Children.Add(row);return input;}
 public bool Validate(out string error){int n;error=null;if(Enabled.IsChecked==true&&(!Int32.TryParse(interval.Text,out n)||n<1||n>52)){error="重复间隔请输入 1～52";return false;}return true;}
 public void Apply(TaskItem task){if(Enabled.IsChecked!=true)return;string kind=repeat.SelectedIndex==1?"week":repeat.SelectedIndex==2?"month":"none";if(kind!=task.RepeatKind||Int32.Parse(interval.Text)!=task.RepeatEvery){task.RepeatNextId="";task.RepeatAnchorDay=0;}task.Project=project.Text.Trim().Substring(0,Math.Min(60,project.Text.Trim().Length));task.Tags=String.Join(",",tags.Text.Split(new[]{',','，',' '},StringSplitOptions.RemoveEmptyEntries).Select(s=>s.Trim()).Where(s=>s.Length>0).Distinct().Take(12));task.RepeatKind=kind;task.RepeatEvery=Int32.Parse(interval.Text);}
}
public partial class MainWindow {
 ComboBox projectFilter;TextBox tagFilter;bool syncingFilters;TextBlock saveState;DateTime lastSaved;bool savePending;DispatcherTimer saveRetry;int saveAttempts;
 FrameworkElement MakeProjectFilters(){var row=new WrapPanel{Margin=new Thickness(0,0,0,7)};projectFilter=new ComboBox{Width=170,Margin=new Thickness(0,0,8,0),Padding=new Thickness(5)};Ui.Name(projectFilter,"按项目筛选");projectFilter.SelectionChanged+=(s,e)=>{if(!syncingFilters){ClearSelection();Refresh();}};row.Children.Add(projectFilter);tagFilter=new TextBox{Width=170,Padding=new Thickness(5),ToolTip="按标签筛选；逗号分隔表示同时包含"};Ui.Name(tagFilter,"按标签筛选");tagFilter.TextChanged+=(s,e)=>{ClearSelection();Refresh();};row.Children.Add(tagFilter);row.Children.Add(Ui.Button("清除筛选",()=>{projectFilter.SelectedIndex=0;tagFilter.Text="";search.Text="";},false,true));return row;}
 void RefreshProjectFilters(){if(projectFilter==null)return;string current=projectFilter.SelectedItem as string??"全部项目";var names=new[]{"全部项目"}.Concat(state.Tasks.Select(t=>t.Project??"").Where(s=>s.Length>0).Distinct().OrderBy(s=>s)).ToArray();syncingFilters=true;projectFilter.ItemsSource=names;projectFilter.SelectedItem=names.Contains(current)?current:names[0];syncingFilters=false;}
 bool MatchTaxonomy(TaskItem t){string project=projectFilter==null?null:projectFilter.SelectedItem as string;if(!String.IsNullOrEmpty(project)&&project!="全部项目"&&!String.Equals(t.Project,project,StringComparison.CurrentCultureIgnoreCase))return false;return tagFilter==null||tagFilter.Text.Split(new[]{',','，',' '},StringSplitOptions.RemoveEmptyEntries).All(tag=>(t.Tags??"").Split(',').Any(value=>String.Equals(tag,value,StringComparison.CurrentCultureIgnoreCase)));}
 bool ApplyEdit(string[] ids,string title,bool useStart,DateTime? start,bool useEnd,DateTime? end,bool useQuadrant,int q,out string error){return ApplyEditWithRules(ids,title,useStart,start,useEnd,end,useQuadrant,q,null,out error);}
 void ShowWeeklySchedule(){CreateWeeklySchedule().ShowDialog();} Window CreateWeeklySchedule(){var w=new Window{Title="每周下班时间",Width=420,Height=590,MaxHeight=SystemParameters.WorkArea.Height-40,Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=Ui.B("#FFF4DA"),Resources=Resources,FontFamily=FontFamily};var panel=new StackPanel{Margin=new Thickness(22)};w.Content=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};panel.Children.Add(Ui.T("留空沿用默认时间；跨夜仍属于原工作日。",12));var inputs=new TextBox[7];var names=new[]{"星期日","星期一","星期二","星期三","星期四","星期五","星期六"};foreach(int day in new[]{1,2,3,4,5,6,0}){int d=day;var row=new DockPanel{Margin=new Thickness(0,7,0,0)};var label=Ui.T(names[d],13);label.Width=100;row.Children.Add(label);inputs[d]=new TextBox{Text=state.WeeklyOffWork[d]??"",Padding=new Thickness(6),ToolTip="例如 18:30；留空使用默认时间"};Ui.Name(inputs[d],names[d]+"下班时间");row.Children.Add(inputs[d]);panel.Children.Add(row);}var useOverride=new CheckBox{Content="临时覆盖本轮工作日",IsChecked=state.WorkOverrideDate.Date==state.WorkdayDate.Date&&!String.IsNullOrWhiteSpace(state.WorkOverrideTime),Margin=new Thickness(0,18,0,6)};panel.Children.Add(useOverride);var value=new TextBox{Text=WorkdayClock.Resolve(state),Padding=new Thickness(6)};Ui.Name(value,"临时下班时间");panel.Children.Add(value);var error=Ui.T("",11,"#BE3152");panel.Children.Add(error);panel.Children.Add(Ui.Button("保存时间安排",()=>{TimeSpan time;for(int d=0;d<7;d++)if(inputs[d].Text.Trim().Length>0&&!WorkdayClock.TryTime(inputs[d].Text,out time)){error.Text=names[d]+"时间无效";return;}if(useOverride.IsChecked==true&&!WorkdayClock.TryTime(value.Text,out time)){error.Text="临时时间无效";return;}state.WeeklyOffWork=inputs.Select(i=>i.Text.Trim()).ToArray();state.WorkOverrideDate=useOverride.IsChecked==true?state.WorkdayDate:DateTime.MinValue;state.WorkOverrideTime=useOverride.IsChecked==true?value.Text.Trim():"";Save();SyncWorkClockInputs();RefreshWorkClock();w.Close();},true));return w;}
 void SyncWorkClockInputs(){syncingWorkClock=true;try{foreach(var field in new[]{mainOffWork,widgetOffWork})if(field!=null)field.Text=WorkdayClock.Resolve(state);}finally{syncingWorkClock=false;}}
 FrameworkElement MakeSaveStatus(){var panel=new StackPanel();saveState=Ui.T("本地保存 · 准备就绪",10,"#8791A6");Ui.Name(saveState,"待办保存状态");panel.Children.Add(saveState);panel.Children.Add(Ui.Button("重试保存",()=>{TryWriteNative();},false,true));if(ManagedBridge.Active)panel.Children.Add(Ui.Button("数据与版本",()=>ManagedBridge.Send("MAINTENANCE"),false,true));return panel;}
 bool SaveManaged(){TryWriteNative();return true;}
 bool TryWriteNative(){try{Data.Save(state);lastSaved=DateTime.Now;savePending=false;saveAttempts=0;if(saveRetry!=null)saveRetry.Stop();if(saveState!=null)saveState.Text="已保存 "+lastSaved.ToString("HH:mm:ss");return true;}catch{savePending=true;saveAttempts++;if(saveState!=null)saveState.Text="尚未保存 · 正在重试（"+saveAttempts+"）";if(saveRetry==null){saveRetry=new DispatcherTimer();saveRetry.Tick+=(s,e)=>TryWriteNative();}saveRetry.Interval=TimeSpan.FromSeconds(Math.Min(30,Math.Pow(2,Math.Min(5,saveAttempts-1))));saveRetry.Start();return false;}}
 public bool BridgeFlushData(){FlushWorkClock();CommitNoteDraft(false);return TryWriteNative()&&!savePending;}
 static T Named<T>(DependencyObject root,string name) where T:DependencyObject{if(root is T&&System.Windows.Automation.AutomationProperties.GetName(root)==name)return (T)root;for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);i++){var found=Named<T>(System.Windows.Media.VisualTreeHelper.GetChild(root,i),name);if(found!=null)return found;}return null;}
