  using(var locked=new FileStream(Data.FileName,FileMode.Open,FileAccess.Read,FileShare.None)){state.Note="保存失败重试测试";Save();Assert(savePending,"failed save remains pending");}Pump(1300);Assert(!savePending&&Data.Read().Note=="保存失败重试测试","save retries after sharing violation");
 }finally{state.Tasks=previous;state.WeeklyOffWork=week;state.WorkOverrideDate=overrideDate;state.WorkOverrideTime=overrideTime;state.Note=oldNote;tagFilter.Text="";projectFilter.SelectedIndex=0;Save();SyncWorkClockInputs();RefreshWorkClock();Refresh();}}
 static IEnumerable<Button> VisualButtons(DependencyObject root){if(root is Button)yield return (Button)root;for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);i++)foreach(var button in VisualButtons(System.Windows.Media.VisualTreeHelper.GetChild(root,i)))yield return button;}
